import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.CazwtNDk.js";const u=JSON.parse('{"title":"AI Access (MCP)","description":"","frontmatter":{},"headers":[],"relativePath":"mcp.md","filePath":"mcp.md","lastUpdated":1789503731000}'),n={name:"mcp.md"};function c(l,e,r,d,i,p){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="ai-access-mcp" tabindex="-1">AI Access (MCP) <a class="header-anchor" href="#ai-access-mcp" aria-label="Permalink to &quot;AI Access (MCP)&quot;">​</a></h1><p>Calendar speaks the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>, so an AI client can read the schedule, look for free time, and — unless the endpoint is read-only — create and change events. Tools call the same service the REST API uses, so recurrence, time zone, and concurrency rules are identical.</p><p>The endpoint is streamable HTTP at <code>&lt;base_path&gt;/mcp</code>. With no <code>base_path</code> that is <code>http://localhost:8080/mcp</code>; with <code>base_path: /calendar</code> it is:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8080/calendar/mcp</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">No Authentication</p><p>The MCP endpoint has no authentication, exactly like the UI and REST API, and it grants the same authority: anything an AI client reaches can read and, by default, rewrite every calendar. Restrict it at deployment, set <code>read_only</code>, or disable it. It is not scoped by the entity filter.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#F07178;">mcp</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  enabled</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> true</span><span style="color:#546E7A;font-style:italic;"> # default; set to false to remove the endpoint entirely</span></span>
<span class="line"><span style="color:#F07178;">  read_only</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> false</span><span style="color:#546E7A;font-style:italic;"> # true publishes only the three read tools</span></span></code></pre></div><p>With <code>read_only: true</code> the write tools are not registered, so a client cannot call them even if it knows their names.</p><h2 id="connect-a-client" tabindex="-1">Connect a Client <a class="header-anchor" href="#connect-a-client" aria-label="Permalink to &quot;Connect a Client&quot;">​</a></h2><p>Most clients accept an HTTP MCP server entry:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">mcpServers</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">calendar</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">      &quot;</span><span style="color:#F78C6C;">type</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">http</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">      &quot;</span><span style="color:#F78C6C;">url</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">http://localhost:8080/calendar/mcp</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">      &quot;</span><span style="color:#F78C6C;">headers</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#F07178;">X-User</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">ai-assistant</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">    }</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p><code>X-User</code> is the optional audit label stored in <code>Updated by</code>. It is not a login and grants nothing; when it is absent, writes are recorded as <code>mcp</code>.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Mode</th><th>Purpose</th></tr></thead><tbody><tr><td><code>list_occurrences</code></td><td>read</td><td>Everything scheduled in a date range, with recurring events expanded</td></tr><tr><td><code>list_events</code></td><td>read</td><td>Search stored events by name, group, or entity; returns ids and repeat rules</td></tr><tr><td><code>find_free_time</code></td><td>read</td><td>Open slots of a given length within working hours</td></tr><tr><td><code>create_event</code></td><td>write</td><td>Create a timed or all-day event, optionally repeating</td></tr><tr><td><code>update_event</code></td><td>write</td><td>Change supplied fields of an event; edits the whole series</td></tr><tr><td><code>cancel_occurrence</code></td><td>write</td><td>Cancel one occurrence, leaving the rest of the series</td></tr><tr><td><code>delete_event</code></td><td>write</td><td>Delete events by id, including every occurrence</td></tr></tbody></table><h3 id="dates-and-times" tabindex="-1">Dates and Times <a class="header-anchor" href="#dates-and-times" aria-label="Permalink to &quot;Dates and Times&quot;">​</a></h3><p>Supply an IANA <code>time_zone</code> such as <code>Europe/Istanbul</code>; it defaults to UTC. Timed values accept RFC3339 (<code>2026-09-15T09:00:00+03:00</code>) or a wall-clock timestamp (<code>2026-09-15T09:00:00</code>) read in that zone. A wall-clock time that does not exist because of a daylight-saving transition is rejected rather than silently moved.</p><p>All-day events use plain dates, and <code>end_date</code> is the <strong>inclusive</strong> last day: <code>start_date: 2026-09-21</code> with <code>end_date: 2026-09-23</code> is a three-day event. Occurrences are reported the same way, so a value read from <code>list_occurrences</code> can be passed straight back to a write tool.</p><h3 id="free-time" tabindex="-1">Free Time <a class="header-anchor" href="#free-time" aria-label="Permalink to &quot;Free Time&quot;">​</a></h3><p><code>find_free_time</code> merges overlapping meetings, treats all-day events as busy for their whole span, and skips weekends unless <code>include_weekends</code> is set. Working hours default to <code>09:00</code>–<code>18:00</code> and are applied on the wall clock, so a slot keeps its local time across a daylight-saving change.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>A range covers at most <strong>400 days</strong> and 20,000 occurrences; exceeding either returns an error rather than a truncated calendar. <code>list_occurrences</code> returns 200 occurrences by default and reports <code>truncated</code> when more exist.</p><h2 id="recurring-events" tabindex="-1">Recurring Events <a class="header-anchor" href="#recurring-events" aria-label="Permalink to &quot;Recurring Events&quot;">​</a></h2><p><code>update_event</code> edits the series. To remove a single occurrence, call <code>cancel_occurrence</code> with the <code>id</code> and the <code>occurrence_start</code> reported by <code>list_occurrences</code>; cancelling the same occurrence twice is harmless. Calendar rejects series timing changes while exceptions exist, so remove the exceptions first. Rescheduling one occurrence is not exposed as a tool — use the UI or the REST API.</p><h2 id="example-requests" tabindex="-1">Example Requests <a class="header-anchor" href="#example-requests" aria-label="Permalink to &quot;Example Requests&quot;">​</a></h2><ul><li>&quot;What is on the team calendar next week?&quot; → <code>list_occurrences</code></li><li>&quot;Find an hour for a design review before Friday&quot; → <code>find_free_time</code>, then <code>create_event</code></li><li>&quot;Move the Monday standup to 10:00&quot; → <code>list_events</code>, then <code>update_event</code></li><li>&quot;Skip next Tuesday&#39;s standup&quot; → <code>list_occurrences</code>, then <code>cancel_occurrence</code></li></ul>`,25)]))}const y=t(n,[["render",c]]);export{u as __pageData,y as default};
